function contextualGreeting(){const now=new Date(),h=now.getHours(),md=`${now.getMonth()+1}-${now.getDate()}`,special={'1-1':'Selamat Tahun Baru','5-1':'Selamat Hari Buruh','6-1':'Selamat Hari Lahir Pancasila','8-17':'Dirgahayu Republik Indonesia','10-2':'Selamat Hari Batik Nasional','11-10':'Selamat Hari Pahlawan','12-25':'Selamat Hari Natal'}[md];if(special)return special;return h<11?'Selamat pagi':h<15?'Selamat siang':h<18?'Selamat sore':'Selamat malam'}
function loadKapuasCatalog(){if(state.ckan.status==='siap')return;const cb='sababukaCkan'+Date.now(),script=document.createElement('script');window[cb]=payload=>{state.ckan={status:payload?.success?'siap':'gagal',count:payload?.result?.count||0,items:(payload?.result?.results||[]).slice(0,5)};delete window[cb];script.remove();render()};script.onerror=()=>{state.ckan.status='gagal';delete window[cb];script.remove();render()};script.src=`https://satudata.kapuaskab.go.id/api/3/action/package_search?rows=5&sort=metadata_modified%20desc&callback=${cb}`;document.head.appendChild(script)}
async function loadBpsCatalog(){const apiKey=window.SABABUKA_CONFIG?.bpsApiKey;if(!apiKey||state.bps.status==='memuat'||state.bps.status==='siap')return;state.bps.status='memuat';try{const result=await getBpsPublications({apiKey,year:state.year});state.bps={status:'siap',total:result.total,items:result.items.slice(0,3).map(item=>({title:item.title,url:item.pdf||'https://kapuaskab.bps.go.id/id/publication',type:'Publikasi WebAPI'}))}}catch(error){state.bps.status='gagal';console.warn('BPS connector:',error.message)}render()}
function liveSourcePanel(){return `<section class="source-trust" aria-label="Contoh jejak sumber dashboard"><div class="source-trust-intro"><span class="eyebrow">Contoh jejak sumber</span><h2>Setiap angka harus membawa asal, periode, dan status pemeriksaan</h2><p>BPS menjadi rujukan statistik resmi; Satu Data menyediakan katalog daerah; OPD tetap menjadi produsen dan pemilik substansi data.</p></div><a class="source-channel bps" href="https://kapuaskab.bps.go.id/id" target="_blank" rel="noopener"><span class="channel-mark">BPS</span><strong>BPS Kabupaten Kapuas</strong><small>Rujukan publik tersedia; nilai belum ditarik otomatis</small><em>BUKA SUMBER RESMI ↗</em></a><a class="source-channel" href="https://satudata.kapuaskab.go.id" target="_blank" rel="noopener"><span class="channel-mark">SD</span><strong>Satu Data Kapuas</strong><small>${state.ckan.status==='siap'?`${fmt(state.ckan.count)} metadata dataset terbaca`:'Katalog CKAN sedang diperiksa'}</small><em>METADATA KATALOG ↗</em></a><button class="source-channel" data-page="validation"><span class="channel-mark">VR</span><strong>Usulan gerbang verifikasi</strong><small>Simulasi data sebelum layak disajikan</small><em>LIHAT ALUR →</em></button></section>`}
function executiveDecisionBrief(){const priorities=[{level:'Contoh skenario 01',title:'Validasi isu kesehatan sebelum dibawa ke forum pimpinan',meta:'Produsen data mengonfirmasi angka dan konteks wilayah',tone:'critical'},{level:'Contoh skenario 02',title:'Hubungkan kondisi infrastruktur dengan akses layanan dasar',meta:'Data lintas OPD dibandingkan tanpa menghilangkan sumber',tone:'warning'},{level:'Contoh skenario 03',title:'Pantau capaian program dan hambatan pelaksanaannya',meta:'Opsi tindak lanjut dibahas bersama OPD terkait',tone:'watch'}];return `<section class="decision-cockpit"><div class="decision-heading"><div><span class="eyebrow">Contoh brief untuk pimpinan</span><h2>Dari data tersebar menjadi bahan pembahasan bersama</h2><p>Konten berikut adalah skenario demonstrasi untuk memperlihatkan alur, bukan penilaian kondisi nyata Kabupaten Kapuas.</p></div><div class="confidence-stamp"><span>CAKUPAN PEMERIKSAAN DEMO</span><strong>10/12</strong><small>bukan skor kualitas resmi</small></div></div><div class="decision-list">${priorities.map((p,i)=>`<button class="decision-item ${p.tone}" data-page="analysis"><span>0${i+1}</span><div><small>${p.level}</small><strong>${p.title}</strong><em>${p.meta}</em></div><b>→</b></button>`).join('')}</div><div class="decision-footer"><span><i class="ok"></i> 10 contoh data lolos simulasi</span><span><i class="wait"></i> 2 contoh data menunggu konfirmasi</span><span>Periode simulasi: Agustus ${state.year}</span><button data-page="analysis">Buka bahan analisis</button></div></section>`}
function applyYear(year){const index=years.indexOf(year),distance=years.length-1-index;indicators.forEach((item,itemIndex)=>{const base=baseDataset.indicators[itemIndex];item.value=base.trend[index];item.prev=base.trend[Math.max(0,index-1)];const targetFactor=base.higher?.88+index*.03:1.20-index*.05;item.target=+(base.target*targetFactor).toFixed(2);const progress=base.higher?item.value/item.target:item.target/item.value;item.status=progress>=1?'good':progress>=.96?'attention':'critical';item.period=base.period.replace('2026',String(year));item.updated=`${20+itemIndex%8} Agu ${year}`});districts.forEach((item,itemIndex)=>{const base=baseDataset.districts[itemIndex],variation=((itemIndex%3)-1)*(distance%2);item.score=Math.max(45,Math.min(95,Math.round(base.score-distance*(1.4+(itemIndex%4)*.25)+variation)));item.poverty=+(base.poverty+distance*(.18+(itemIndex%3)*.04)-variation*.03).toFixed(1);item.stunting=Math.round(base.stunting+distance*(1.1+(itemIndex%4)*.25)-variation*.2);item.roads=Math.max(35,Math.round(base.roads-distance*(2.1+(itemIndex%3)*.35)+variation))});opds.forEach((item,itemIndex)=>{const base=baseDataset.opds[itemIndex],variation=((itemIndex%4)-1.5)*(distance%2);item.score=Math.max(55,Math.min(98,Math.round(base.score-distance*(1.2+(itemIndex%3)*.35)+variation)));item.status=item.score>=82?'Baik':'Perlu Perhatian';item.updated=year===2026?base.updated:`Data ${year}`});const volumeFactors=[.76,.83,.89,.95,1];services.forEach((item,itemIndex)=>{const base=baseDataset.services[itemIndex],factor=volumeFactors[index],variation=1+(((itemIndex%3)-1)*.015*distance);item.volume=Math.round(base.volume*factor*variation);item.done=Math.round(item.volume*(base.done/base.volume-(distance*.008)));item.satisfaction=+(base.satisfaction-distance*(.7+(itemIndex%2)*.2)).toFixed(1);item.time=+(base.time+distance*(.12+(itemIndex%3)*.03)).toFixed(1)});const financeFactors=[.72,.79,.86,.93,1],factor=financeFactors[index];finance.income=+(baseDataset.finance.income*factor).toFixed(2);finance.budget=+(baseDataset.finance.budget*(.82+index*.045)).toFixed(2);finance.spend=+(baseDataset.finance.spend*factor*(.96+index*.01)).toFixed(3);finance.absorption=+(finance.spend/finance.budget*100).toFixed(1);finance.targetIncome=+(baseDataset.finance.targetIncome*factor).toFixed(2);finance.monthly=baseDataset.finance.monthly.map((value,month)=>+(value*(.90+index*.025)+((month%2?1:-1)*distance*.55)).toFixed(1))}
function toast(msg,type='success'){const el=document.createElement('div');el.className='toast '+type;el.textContent=msg;document.querySelector('#toast-root').appendChild(el);setTimeout(()=>el.remove(),2600)}
function icon(c){return `<span aria-hidden="true">${c}</span>`}
function sidebar(){return `<aside class="sidebar ${state.collapsed?'collapsed':''} ${state.mobile?'mobile-open':''}"><div class="brand"><div class="brand-mark">S</div><div class="brand-text"><strong>SABABUKA</strong><span>Sistem Analisis Big Data<br>Kabupaten Kapuas</span></div></div><nav aria-label="Navigasi utama">${menu.map(m=>m[0]==='section'?`<div class="nav-section">${m[2]}</div>`:`<button class="nav-item ${state.page===m[0]?'active':''}" data-page="${m[0]}" aria-label="${m[2]}"><span class="nav-icon">${m[1]}</span><span class="nav-label">${m[2]}</span></button>`).join('')}</nav><div class="sidebar-foot"><button class="nav-item" id="collapseBtn"><span class="nav-icon">${state.collapsed?'»':'«'}</span><span class="nav-label">Perkecil sidebar</span></button></div></aside>`}
function header(){const bapp=state.role==='bapperida';return `<header class="topbar"><button class="icon-btn mobile-menu" id="mobileMenu" aria-label="Buka navigasi">☰</button><div class="topbar-left"><div><div class="topbar-title">${titleMap[state.page]}</div><div class="topbar-meta"><strong>PROTOTIPE · DATA DEMONSTRASI</strong> · bukan dasar keputusan resmi</div></div></div><div class="spacer"></div><div class="top-controls"><select class="select role-select" id="roleSelect" aria-label="Pilih ruang kerja"><option value="bupati" ${!bapp?'selected':''}>Contoh Tampilan Pimpinan</option><option value="bapperida" ${bapp?'selected':''}>Contoh Ruang Verifikasi</option></select><span class="topbar-meta period">Periode simulasi: Agustus ${state.year}</span><select class="select" id="yearSelect" aria-label="Filter tahun">${years.map(y=>`<option ${y===state.year?'selected':''}>${y}</option>`).join('')}</select><button class="icon-btn" id="searchBtn" aria-label="Pencarian">⌕</button><button class="btn soft presentation-btn" id="presentationBtn">▣ ${state.presentation?'Keluar Presentasi':'Mode Presentasi'}</button><div class="profile ${state.profile?'open':''}" id="profile"><div class="avatar">${bapp?'VR':'PI'}</div><div><div class="profile-name">${bapp?'Simulasi Verifikator':'Tampilan Pimpinan'}</div><div class="profile-role">${bapp?'Usulan alur BAPPERIDA':'Prototipe Eksekutif'}</div></div><div class="profile-menu"><button data-action="help">Panduan Presentasi</button></div></div></div></header>`}
function metricCard(label,value,delta,tone,ico){return `<article class="metric" data-action="metric"><div class="metric-top"><div class="label">${label}</div><div class="metric-icon ${tone}">${ico}</div></div><div class="value">${value}</div><div class="delta">${delta}</div></article>`}
function badge(status){const c=status==='Baik'||status==='Terhubung'||status==='Selesai'?'good':status==='Kritis'||status==='Bermasalah'?'critical':'attention';return `<span class="badge ${c}">${status}</span>`}
function indicatorCard(i){let change=i.value-i.prev;let positive=i.higher?change>=0:change<=0;const k=indicatorKnowledge[i.id],verified=!['stunting','roads'].includes(i.id),sourceType=k.primary.includes('BPS')?'BPS':i.opd;return `<article class="indicator indicator-clickable" data-detail="indicator:${i.id}" tabindex="0" role="button" aria-label="Buka penjelasan ${i.name}"><div class="indicator-head"><div><div class="indicator-name">${i.name}</div><small class="indicator-source">${sourceType} · ${verified?'Contoh lolos pemeriksaan':'Perlu konfirmasi'}</small></div><span class="data-seal ${verified?'verified':'pending'}">${verified?'SIMULASI LOLOS':'PERLU KONFIRMASI'}</span></div><div class="indicator-value">${fmt(i.value)} <small>${i.unit}</small></div><div class="indicator-row"><span>Target ${fmt(i.target)} ${i.unit}</span>${badge(statusLabel(i.status))}</div><div class="progress"><span class="status-${statusClass(i.status)}" style="width:${pct(i)}%"></span></div><div class="indicator-row"><span class="${positive?'trend-up':'trend-down'}">${change>=0?'↑':'↓'} ${fmt(Math.abs(change))} dari periode lalu</span><span>${pct(i)}%</span></div><div class="indicator-row"><span class="opd">${i.opd}</span><span>${i.updated}</span></div></article>`}
function trendChart(){const map={Ekonomi:'growth',Kemiskinan:'poverty',Kesehatan:'stunting',Pendidikan:'hdi'};const i=indicators.find(x=>x.id===map[state.chartTab]);const max=Math.max(...i.trend,i.target)*1.18;return `<div class="tabs">${Object.keys(map).map(t=>`<button class="tab ${state.chartTab===t?'active':''}" data-tab="${t}">${t}</button>`).join('')}</div><div class="chart" aria-label="Grafik tren ${state.chartTab}">${i.trend.map((v,idx)=>`<div class="bar-col"><div class="bar" style="height:${v/max*100}%" data-tip="${years[idx]}: ${fmt(v)} ${i.unit}"></div><div class="bar target" style="height:${i.target/max*100}%" data-tip="Target: ${fmt(i.target)}"></div><span class="axis-label">${years[idx]}</span></div>`).join('')}</div><div style="margin-top:24px;font-size:11px;color:var(--muted)">Nilai ${years.at(-1)} <strong style="color:var(--ink)">${fmt(i.value)} ${i.unit}</strong> · Target <strong style="color:var(--ink)">${fmt(i.target)} ${i.unit}</strong></div>`}
function districtGrid(){return `<div class="legend"><span><i class="mini-dot" style="background:var(--green)"></i>Baik</span><span><i class="mini-dot" style="background:var(--amber)"></i>Perlu perhatian</span><span><i class="mini-dot" style="background:var(--red)"></i>Prioritas</span></div><div class="map-grid" style="margin-top:12px">${districts.map(d=>`<button class="district ${state.district===d.name?'active':''}" data-district="${d.name}"><i class="district-status" style="background:${d.score>=80?'var(--green)':d.score>=68?'var(--amber)':'var(--red)'}"></i><strong>${d.name}</strong><span>Skor ${d.score}</span></button>`).join('')}</div>`}
function alertsList(limit=5){return `<div class="alert-list">${alerts.slice(0,limit).map(a=>`<div class="alert"><div class="alert-strip" style="background:${a.urgency==='Kritis'?'var(--red)':a.urgency==='Tinggi'?'var(--amber)':'#4388cc'}"></div><div><div class="alert-title">${a.title}</div><div class="alert-meta">${a.opd} · ${a.time} · ${a.urgency}</div></div><button class="btn" data-detail="alert:${a.id}">Tinjau</button></div>`).join('')}</div>`}
function opdTable(){return `<div class="table-wrap"><table><thead><tr><th>OPD</th><th>Jumlah Indikator</th><th>Capaian</th><th>Status Data</th><th>Pembaruan</th><th>Aksi</th></tr></thead><tbody>${opds.slice(0,7).map(o=>`<tr><td><strong>${o.name}</strong></td><td>${o.count}</td><td>${o.score}%</td><td>${badge(o.status)}</td><td>${o.updated}</td><td><button class="btn" data-detail="opd:${o.id}">Detail</button></td></tr>`).join('')}</tbody></table></div>`}
function summary(){let crit=indicators.filter(i=>i.status==='critical').length,good=indicators.filter(i=>i.status==='good').length;return `<section class="executive-hero"><div><span class="eyebrow">SABABUKA COMMAND BRIEF · ${state.year}</span><h1>${contextualGreeting()}, Bapak Bupati</h1><p>Satu pandangan untuk membaca kondisi daerah, memastikan sumber data, dan menentukan tindak lanjut lintas perangkat daerah.</p><div class="hero-tags"><span>● Data lintas OPD</span><span>● Jejak sumber tersedia</span><span>● Disaring BAPPERIDA</span></div></div><div class="hero-actions"><button class="btn light" data-action="report">Unduh brief pimpinan</button><button class="btn outline-light" data-page="analysis">Lihat rekomendasi</button></div></section>${executiveDecisionBrief()}<div class="metrics executive-metrics">${metricCard('Layak Tampil',10,'Lolos verifikasi BAPPERIDA','green','✓')}${metricCard('Capaian Sesuai Target',good,`${indicators.length} indikator strategis`,'blue','↗')}${metricCard('Risiko Kritis',crit,'Membutuhkan keputusan lintas OPD','red','!')}${metricCard('Menunggu Konfirmasi',2,'Tidak dipakai sebagai dasar final','amber','◴')}</div>${liveSourcePanel()}<div class="section-head"><div><span class="eyebrow">Panel indikator</span><h2>Indikator strategis terkurasi</h2><p>Setiap angka membawa sumber, periode, status verifikasi, target, dan pemilik tindak lanjut.</p></div><button class="btn" data-page="validation">Lihat kendali mutu</button></div><div class="indicator-grid">${indicators.map(indicatorCard).join('')}</div><div class="two-col"><div class="card"><div class="card-title"><h3>Tren Strategis 2022–2026</h3><span>Aktual vs target</span></div>${trendChart()}</div><div class="card"><div class="card-title"><h3>Capaian Menurut Bidang</h3><span>Agustus ${state.year}</span></div><div class="hbars">${[['Kesehatan',82],['Pendidikan',88],['Infrastruktur',76],['Ekonomi',86],['Ketahanan Pangan',79],['Pelayanan Publik',90]].map(x=>`<div class="hrow"><span>${x[0]}</span><div class="htrack"><div class="hfill" style="width:${x[1]}%"></div></div><strong>${x[1]}%</strong></div>`).join('')}</div></div></div><div class="two-col"><div class="card"><div class="card-title"><h3>Wilayah yang Perlu Dicermati</h3><span>17 kecamatan · klik untuk profil sumber</span></div>${districtGrid()}</div><div class="card"><div class="card-title"><h3>Peringatan Prioritas</h3><button class="btn" data-page="alerts">Lihat Semua</button></div>${alertsList(5)}</div></div><section class="source-governance"><div><div class="eyebrow">Aturan penggunaan data</div><h2>Data lintas platform dinormalisasi, tetapi identitas sumber tidak dihilangkan</h2></div><div class="source-rule"><strong>Statistik resmi</strong><p>${sourceRule.official}</p></div><div class="source-rule"><strong>Data sektoral OPD</strong><p>${sourceRule.sectoral}</p></div><div class="source-rule"><strong>Rujukan perencanaan</strong><p>${sourceRule.planning}</p></div><div class="source-conflict"><strong>Jika ditemukan perbedaan</strong><p>${sourceRule.conflict}</p></div></section>`}
function meetingSummary(){
  let html=summary().replace('SABABUKA COMMAND BRIEF','PROTOTIPE INTEGRASI DATA').replace('Satu pandangan untuk membaca kondisi daerah, memastikan sumber data, dan menentukan tindak lanjut lintas perangkat daerah.','Contoh bagaimana data lintas platform dapat diringkas, ditelusuri sumbernya, dan dibahas bersama sebelum menjadi bahan pimpinan.').replace('● Disaring BAPPERIDA','● Contoh alur verifikasi').replace('Lihat rekomendasi','Lihat bahan analisis').replace('Layak Tampil','Lolos Simulasi').replace('Lolos verifikasi BAPPERIDA','Contoh setelah pemeriksaan').replace('Capaian Sesuai Target','Contoh Capaian Target').replace('indikator strategis','indikator demonstrasi').replace('Risiko Kritis','Skenario Perhatian').replace('Membutuhkan keputusan lintas OPD','Contoh kebutuhan koordinasi').replace('Menunggu Konfirmasi','Belum Dikonfirmasi').replace('Indikator strategis terkurasi','Contoh indikator strategis').replace('Setiap angka membawa sumber, periode, status verifikasi, target, dan pemilik tindak lanjut.','Seluruh nilai di bawah adalah data demonstrasi untuk menguji bentuk penyajian dan workflow.').replace('Lihat kendali mutu','Lihat simulasi kendali mutu');
  const riskyStart='<div class="two-col"><div class="card"><div class="card-title"><h3>Wilayah yang Perlu Dicermati';
  const safeResume='<section class="source-governance">';
  const start=html.indexOf(riskyStart),resume=html.indexOf(safeResume,start);
  if(start>=0&&resume>start)html=html.slice(0,start)+html.slice(resume);
  return html;
}
function meetingAnalysis(){return analysisPage().replace('Analisis dan Rekomendasi','Bahan Analisis').replace('Temuan sistem untuk bahan pertimbangan pimpinan','Contoh cara sistem menyusun bahan diskusi; keputusan tetap berada pada forum dan pejabat berwenang').replace('Brief pimpinan · 28 Agustus 2026','SKENARIO DEMONSTRASI · BUKAN KONDISI AKTUAL').replace('Delapan indikator menguat, tetapi tiga hambatan perlu keputusan lintas OPD.','Contoh bagaimana beberapa indikator dapat dibaca bersama tanpa menilai kinerja OPD secara sepihak.').replace('Keputusan yang dibutuhkan','Contoh agenda pembahasan').replace('Satukan verifikasi data dan rencana percepatan dalam satu forum pimpinan.','Konfirmasi data bersama produsen data sebelum merumuskan opsi tindak lanjut.').replace('Lokasi yang perlu didahulukan','Contoh analisis wilayah').replace('Tiga wilayah membentuk kantong risiko yang sama','Pola lintas sektor dapat ditampilkan setelah data wilayah dikonfirmasi').replace('Intervensi utama dan pemilik tindak lanjut','Contoh isu dan pihak yang perlu diajak berdiskusi').replace('Satu pekan untuk mengubah temuan menjadi keputusan','Contoh alur dari temuan menuju pembahasan').replaceAll('Mandau Talawang','Wilayah Contoh A').replaceAll('Pasak Talawang','Wilayah Contoh B').replaceAll('Kapuas Hulu','Wilayah Contoh C').replace('Dinas Kesehatan, DPUPRPKP, Dinas Pertanian, dan tiga kecamatan terkait.','Produsen data, pengampu teknis, perencana, dan wilayah terkait.')}
function meetingSources(){return sourcesPage().replace('Rujukan Publik BPS</div><div class="metric-icon green">BPS</div></div><div class="value">Aktif','Rujukan Publik BPS</div><div class="metric-icon green">BPS</div></div><div class="value">Tersedia').replace('RUJUKAN AKTIF','RUJUKAN PUBLIK').replace('Sumber publik resmi telah dipasang sebagai rujukan provenance.','Sumber publik resmi ditampilkan sebagai contoh provenance.').replace('Sinkronisasi semua sumber','Pemeriksaan sumber demo').replace('Website OPD Diaudit','Sumber OPD Dipetakan').replace('Enam bidang prioritas','Enam contoh bidang').replace('OPD Prioritas','Contoh Sumber OPD').replace('Audit akses publik 12 September 2026','Pemetaan awal kanal publik · perlu konfirmasi OPD').replaceAll('Perlu Endpoint','Perlu Kesepakatan Akses').replaceAll('Website aktif; API dan RSS publik menolak akses otomatis','Kanal publik tersedia; pola pertukaran data perlu disepakati').replaceAll('Website aktif; nilai perlu berita acara verifikasi dan rujukan BPS','Nilai perlu konfirmasi produsen data dan rujukan statistik').replaceAll('Website aktif; konten publik dominan berupa berita','Kanal data terstruktur perlu disepakati').replaceAll('dibutuhkan GeoJSON/WFS atau API','format geospasial dan mekanisme akses perlu disepakati')}
function meetingValidation(){return validationPage().replace('Ruang Verifikasi BAPPERIDA','Simulasi Gerbang Verifikasi').replace('Gerbang kendali mutu sebelum angka dapat muncul pada Ringkasan Bupati','Usulan workflow untuk dibahas bersama BAPPERIDA, Diskominfosantik, BPS, dan produsen data OPD').replace('Pratinjau Summary Bupati','Pratinjau Ringkasan Pimpinan').replace('Verifikasi BAPPERIDA','Pemeriksaan terkoordinasi').replace('Publikasi','Penyajian terbatas').replace('Masuk Summary Bupati','Pratinjau untuk pimpinan').replace('Menunggu Validasi','Contoh Menunggu').replace('Sedang Diperiksa','Contoh Diperiksa').replace('Siap disajikan kepada pimpinan','Ilustrasi setelah seluruh syarat dipenuhi').replace('Minta Perbaikan','Contoh Perbaikan').replace('Dikembalikan ke produsen data','Ilustrasi pengembalian ke produsen data').replace('Empat syarat sebelum data masuk ke ruang Bupati','Empat syarat yang diusulkan sebelum data disajikan kepada pimpinan').replace('Persetujuan akan mengubah status data menjadi layak tayang pada sesi demonstrasi.','Aksi berikut hanya mensimulasikan perubahan status di browser dan belum merupakan persetujuan kedinasan.')}
function meetingFinance(){
  const guide=`<section class="quality-gate"><div><span class="eyebrow">Bahan penyepakatan metode</span><h2>Angka berikut hanya contoh struktur, bukan posisi keuangan resmi</h2><p>Forum pilot perlu menyepakati sumber, periode, basis pencatatan, level rincian, dan pejabat yang mengesahkan sebelum modul ini dipakai.</p></div><ul><li><strong>Sumber otoritatif</strong><span>Tentukan peran BPKAD, Bapenda, dan sistem keuangan resmi.</span></li><li><strong>Definisi realisasi</strong><span>Sepakati bruto/neto, kas/akrual, cut-off, dan perlakuan koreksi.</span></li><li><strong>Hak akses</strong><span>Bedakan data internal, bahan pimpinan, dan informasi publik.</span></li><li><strong>Rincian aman</strong><span>Rincian per OPD ditampilkan hanya setelah data dan mandat disepakati.</span></li></ul></section>`;
  let html=financePage().replace('Keuangan Daerah','Rancangan Modul Keuangan').replace('Ringkasan pendapatan, belanja, dan penyerapan APBD','Contoh tampilan untuk menyepakati kebutuhan, sumber, definisi, dan tingkat keterbukaan data').replace('Ekspor Ringkasan','Ekspor Contoh').replace('Pendapatan Daerah','Contoh Pendapatan').replace('Belanja Daerah','Contoh Belanja').replace('Penyerapan Anggaran','Contoh Penyerapan').replace('Selisih terhadap Target','Contoh Selisih Target').replace('Perlu akselerasi Agustus–September','Contoh bahan konfirmasi forum');
  html=html.replace('</div><div class="finance-grid">',`</div>${guide}<div class="finance-grid">`);
  const detailStart='<div class="section-head"><div><h2>Ringkasan Perangkat Daerah';
  const detailIndex=html.indexOf(detailStart);
  if(detailIndex>=0)html=html.slice(0,detailIndex);
  return html;
}
function meetingServices(){
  const guide=`<section class="quality-gate"><div><span class="eyebrow">Bahan penyepakatan metode</span><h2>Modul ini menunjukkan pertanyaan yang perlu dijawab bersama</h2><p>Nilai di bawah adalah data demonstrasi. Forum pilot perlu memilih layanan prioritas dan menyepakati definisi sebelum membandingkan capaian.</p></div><ul><li><strong>Cakupan layanan</strong><span>Pilih 3–5 layanan awal dengan volume dan manfaat publik yang jelas.</span></li><li><strong>Definisi selesai</strong><span>Sepakati kapan permohonan dianggap diterima, diproses, dan selesai.</span></li><li><strong>Standar waktu</strong><span>Gunakan SLA resmi masing-masing layanan, bukan ambang buatan sistem.</span></li><li><strong>Kepuasan dan pengaduan</strong><span>Sepakati instrumen, periode, kanal, dan cara mencegah hitung ganda.</span></li></ul></section>`;
  let html=servicesPage().replace('Pelayanan Publik','Rancangan Modul Pelayanan Publik').replace('Volume, kecepatan penyelesaian, kepuasan dan isu layanan','Contoh tampilan untuk menyepakati layanan prioritas, definisi, SLA, dan sumber data').replace('Jumlah Layanan','Contoh Volume Layanan').replace('Permohonan Selesai','Contoh Penyelesaian').replace('Rata-rata Penyelesaian','Contoh Waktu Layanan').replace('Pengaduan Terbuka','Contoh Pengaduan').replace('Lebih cepat 0,3 hari','Perlu definisi SLA resmi').replace('12 membutuhkan tindak lanjut','Perlu klasifikasi tindak lanjut').replace('Kepuasan menurut Kategori','Contoh Indeks Kepuasan').replace('Layanan dengan Volume Tertinggi','Contoh Data Per Jenis Layanan').replaceAll('Perlu Perhatian','Perlu Konfirmasi').replaceAll('Kritis','Perlu Dibahas').replaceAll('Baik','Sesuai Contoh');
  return html.replace('</div><div class="service-grid">',`</div>${guide}<div class="service-grid">`);
}
function commonHead(title,desc,actions=''){return `<div class="page-head"><div><h1>${title}</h1><p>${desc}</p></div><div class="filterbar">${actions}</div></div>`}
function mapPage(){const d=districts.find(x=>x.name===state.district);const sorted=[...districts].sort((a,b)=>b.score-a.score);return `${commonHead('Analisis Wilayah','Perbandingan capaian dan prioritas 17 kecamatan',`<select class="select" id="indicatorSelect"><option>Kemiskinan</option><option>Stunting</option><option>Pendidikan</option><option>Infrastruktur Jalan</option><option>Produksi Pertanian</option><option>Pelayanan Publik</option></select><select class="select"><option>${state.year}</option></select>`)}<div class="two-col"><div class="card"><div class="card-title"><h3>Representasi Wilayah Kecamatan</h3><span>Pilih kecamatan untuk melihat detail</span></div>${districtGrid()}</div><div class="card"><div class="card-title"><h3>${d.name}</h3>${badge(d.score>=80?'Baik':d.score>=68?'Perlu Perhatian':'Kritis')}</div><div class="kpi-strip"><div><span class="topbar-meta">Skor</span><div class="indicator-value">${d.score}</div></div><div><span class="topbar-meta">Kemiskinan</span><div class="indicator-value">${d.poverty}%</div></div><div><span class="topbar-meta">Stunting</span><div class="indicator-value">${d.stunting}%</div></div><div><span class="topbar-meta">Jalan Mantap</span><div class="indicator-value">${d.roads}%</div></div></div><div class="chart" style="height:150px;margin-top:12px">${[d.score-8,d.score-5,d.score-3,d.score-1,d.score].map((v,i)=>`<div class="bar-col"><div class="bar" style="height:${v}%" data-tip="${years[i]}: ${v}"></div><span class="axis-label">${years[i]}</span></div>`).join('')}</div></div></div><div class="two-col"><div class="card"><div class="card-title"><h3>Ranking Kecamatan</h3><span>Skor komposit</span></div><div class="rank-list">${sorted.slice(0,9).map((x,i)=>`<div class="rank-row"><div class="rank-num">${i+1}</div><strong>${x.name}</strong><div class="htrack"><div class="hfill" style="width:${x.score}%"></div></div><strong>${x.score}</strong></div>`).join('')}</div></div><div class="card"><div class="card-title"><h3>Tabel Seluruh Kecamatan</h3></div><div class="table-wrap" style="max-height:320px"><table><thead><tr><th>Kecamatan</th><th>Skor</th><th>Kemiskinan</th><th>Stunting</th><th>Jalan</th></tr></thead><tbody>${sorted.map(x=>`<tr data-district="${x.name}" style="cursor:pointer"><td><strong>${x.name}</strong></td><td>${x.score}</td><td>${x.poverty}%</td><td>${x.stunting}%</td><td>${x.roads}%</td></tr>`).join('')}</tbody></table></div></div></div>`}
function opdPage(){const filtered=opds.filter(o=>(state.status==='Semua'||o.status===state.status)&&(state.search===''||o.name.toLowerCase().includes(state.search.toLowerCase())));return `${commonHead('Kinerja OPD','Pemantauan capaian indikator dan kedisiplinan pembaruan data',`<input class="search" id="opdSearch" value="${state.search}" placeholder="Cari OPD"><select class="select" id="statusFilter"><option>Semua</option><option>Baik</option><option>Perlu Perhatian</option></select><button class="btn" data-action="reset">Reset</button>`)}<div class="metrics">${metricCard('OPD Terpantau',opds.length,'11 OPD prioritas','blue','◫')}${metricCard('Capaian Baik',opds.filter(x=>x.status==='Baik').length,'Mayoritas stabil','green','✓')}${metricCard('Perlu Perhatian',opds.filter(x=>x.status!=='Baik').length,'Fokus tindak lanjut','amber','!')}${metricCard('Data Terlambat',2,'Perlu percepatan pembaruan','red','⏱')}</div><div class="two-col"><div class="card"><div class="card-title"><h3>Ranking Capaian OPD</h3></div><div class="rank-list">${[...opds].sort((a,b)=>b.score-a.score).map((o,i)=>`<div class="rank-row"><div class="rank-num">${i+1}</div><strong>${o.name}</strong><div class="htrack"><div class="hfill" style="width:${o.score}%"></div></div><strong>${o.score}%</strong></div>`).join('')}</div></div><div class="card"><div class="card-title"><h3>Matriks Status Indikator</h3></div>${indicators.slice(0,9).map(i=>`<div class="indicator-row" style="padding:8px 0;border-bottom:1px solid var(--line)"><strong>${i.name}</strong>${badge(statusLabel(i.status))}</div>`).join('')}</div></div><div class="section-head"><div><h2>Tabel Kinerja OPD</h2><p>Klik Detail untuk membuka ringkasan perangkat daerah</p></div></div>${filtered.length?`<div class="table-wrap"><table><thead><tr><th>OPD</th><th>Indikator</th><th>Capaian</th><th>Status</th><th>Pembaruan</th><th>Aksi</th></tr></thead><tbody>${filtered.map(o=>`<tr><td><strong>${o.name}</strong></td><td>${o.count}</td><td>${o.score}%</td><td>${badge(o.status)}</td><td>${o.updated}</td><td><button class="btn" data-detail="opd:${o.id}">Detail</button></td></tr>`).join('')}</tbody></table></div>`:`<div class="card empty"><div class="big">⌕</div><strong>Tidak ada OPD yang sesuai filter</strong><p>Ubah filter atau reset pencarian.</p></div>`}`}
function financePage(){return `${commonHead('Keuangan Daerah','Ringkasan pendapatan, belanja, dan penyerapan APBD',`<button class="btn" data-action="export">⇩ Ekspor Ringkasan</button>`)}<div class="finance-grid">${metricCard('Pendapatan Daerah','Rp1,42 T','Target berjalan Rp1,36 T','green','↗')}${metricCard('Belanja Daerah','Rp1,36 T','Dari pagu Rp2,31 T','blue','▤')}${metricCard('Penyerapan Anggaran','58,7%','Target periode 60,0%','amber','◴')}${metricCard('Selisih terhadap Target','-1,3 pt','Perlu akselerasi Agustus–September','red','!')}</div><div class="two-col"><div class="card"><div class="card-title"><h3>Target vs Realisasi Bulanan</h3><span>Persen penyerapan</span></div><div class="chart">${finance.monthly.map((v,i)=>`<div class="bar-col"><div class="bar" style="height:${v/70*100}%" data-tip="Realisasi ${v}%"></div><div class="bar target" style="height:${(45+i*4)/70*100}%" data-tip="Target ${45+i*4}%"></div><span class="axis-label">${['Mar','Apr','Mei','Jun','Jul','Agu'][i]}</span></div>`).join('')}</div></div><div class="card"><div class="card-title"><h3>Komposisi Belanja</h3></div><div class="hbars">${finance.composition.map(x=>`<div class="hrow"><span>${x[0]}</span><div class="htrack"><div class="hfill" style="width:${x[1]}%"></div></div><strong>${x[1]}%</strong></div>`).join('')}</div></div></div><div class="section-head"><div><h2>Ringkasan Perangkat Daerah</h2></div></div><div class="table-wrap"><table><thead><tr><th>Perangkat Daerah</th><th>Pagu</th><th>Realisasi</th><th>Penyerapan</th><th>Status</th></tr></thead><tbody>${opds.slice(0,9).map((o,i)=>`<tr><td><strong>${o.name}</strong></td><td>Rp${[186,244,315,428,168,237,152,133,96][i]} M</td><td>Rp${Math.round([186,244,315,428,168,237,152,133,96][i]*o.score/100*.72)} M</td><td>${Math.round(o.score*.72)}%</td><td>${badge(o.score>86?'Baik':o.score>78?'Perlu Perhatian':'Kritis')}</td></tr>`).join('')}</tbody></table></div>`}
function servicesPage(){const total=services.reduce((s,x)=>s+x.volume,0),done=services.reduce((s,x)=>s+x.done,0);return `${commonHead('Pelayanan Publik','Volume, kecepatan penyelesaian, kepuasan dan isu layanan') }<div class="service-grid">${metricCard('Jumlah Layanan',total.toLocaleString('id-ID'),'6 kelompok layanan','blue','◎')}${metricCard('Permohonan Selesai',done.toLocaleString('id-ID'),`${Math.round(done/total*100)}% dari permohonan`,'green','✓')}${metricCard('Rata-rata Penyelesaian','2,7 hari','Lebih cepat 0,3 hari','green','◴')}${metricCard('Pengaduan Terbuka','87','12 membutuhkan tindak lanjut','amber','!')}</div><div class="two-col"><div class="card"><div class="card-title"><h3>Tren Volume Layanan</h3><span>Mar–Agu 2026</span></div><div class="chart">${[62,68,73,78,84,91].map((v,i)=>`<div class="bar-col"><div class="bar" style="height:${v}%" data-tip="${['Mar','Apr','Mei','Jun','Jul','Agu'][i]}: ${v*820}"></div><span class="axis-label">${['Mar','Apr','Mei','Jun','Jul','Agu'][i]}</span></div>`).join('')}</div></div><div class="card"><div class="card-title"><h3>Kepuasan menurut Kategori</h3></div><div class="hbars">${services.map(x=>`<div class="hrow"><span>${x.name.split(' ')[0]}</span><div class="htrack"><div class="hfill" style="width:${x.satisfaction}%"></div></div><strong>${x.satisfaction}</strong></div>`).join('')}</div></div></div><div class="section-head"><div><h2>Layanan dengan Volume Tertinggi</h2></div></div><div class="table-wrap"><table><thead><tr><th>Layanan</th><th>Volume</th><th>Selesai</th><th>Rata-rata Waktu</th><th>Kepuasan</th><th>Status</th></tr></thead><tbody>${services.map(s=>`<tr><td><strong>${s.name}</strong></td><td>${s.volume.toLocaleString('id-ID')}</td><td>${s.done.toLocaleString('id-ID')}</td><td>${s.time} hari</td><td>${s.satisfaction}</td><td>${badge(s.satisfaction>=88?'Baik':s.satisfaction>=85?'Perlu Perhatian':'Kritis')}</td></tr>`).join('')}</tbody></table></div>`}
function analysisPage(){return `${commonHead('Analisis dan Rekomendasi','Temuan sistem untuk bahan pertimbangan pimpinan',`<select class="select"><option>Semua Bidang</option><option>Kesehatan</option><option>Infrastruktur</option><option>Ekonomi</option></select><select class="select"><option>Semua Urgensi</option><option>Kritis</option><option>Tinggi</option></select><button class="btn" data-action="reset">Reset</button>`)}<section class="analysis-brief"><div class="analysis-lead"><div class="brief-kicker">Brief pimpinan · 28 Agustus 2026</div><h2>Delapan indikator menguat, tetapi tiga hambatan perlu keputusan lintas OPD.</h2><p>Stunting, kondisi jalan, dan produksi padi bergerak ke arah yang benar namun masih tertinggal dari target tahunan. Keputusan minggu ini sebaiknya menjaga momentum perbaikan sambil membuka hambatan pelaksanaan.</p><div class="brief-signal"><span>8 <small>dari 12 indikator membaik</small></span><span>3 <small>indikator kritis</small></span><span>3 <small>wilayah prioritas</small></span></div></div><aside class="decision-note"><span class="decision-label">Keputusan yang dibutuhkan</span><strong>Satukan verifikasi data dan rencana percepatan dalam satu forum pimpinan.</strong><p>Libatkan Dinas Kesehatan, DPUPRPKP, Dinas Pertanian, dan tiga kecamatan dengan skor terendah.</p><button class="btn primary" data-page="alerts">Buka Pusat Peringatan</button></aside></section><section class="analysis-focus"><div class="focus-heading"><span class="focus-index">01</span><div><div class="eyebrow">Lokasi yang perlu didahulukan</div><h3>Tiga wilayah membentuk kantong risiko yang sama</h3></div></div><div class="territory-strip"><div><span>Mandau Talawang</span><strong>61</strong><small>Stunting 28% · Jalan 49%</small></div><div><span>Pasak Talawang</span><strong>63</strong><small>Stunting 27% · Jalan 52%</small></div><div><span>Kapuas Hulu</span><strong>64</strong><small>Stunting 26% · Jalan 55%</small></div></div><p class="focus-summary">Pola yang berulang menunjukkan kebutuhan intervensi terpadu, bukan program sektoral yang berjalan sendiri-sendiri.</p></section><section class="intervention-board"><div class="focus-heading"><span class="focus-index">02</span><div><div class="eyebrow">Celah terhadap target 2026</div><h3>Intervensi utama dan pemilik tindak lanjut</h3></div></div><div class="intervention-row"><div class="intervention-name"><span class="risk-dot red-dot"></span><strong>Prevalensi stunting</strong><small>Dinas Kesehatan</small></div><div class="intervention-progress"><span style="width:78%"></span></div><div class="intervention-value"><strong>19,8%</strong><small>Target 18,0%</small></div><p>Validasi sasaran dan percepat tindak lanjut keluarga berisiko.</p></div><div class="intervention-row"><div class="intervention-name"><span class="risk-dot amber-dot"></span><strong>Jalan kondisi mantap</strong><small>DPUPRPKP</small></div><div class="intervention-progress"><span style="width:68%"></span></div><div class="intervention-value"><strong>68,4%</strong><small>Target 72,0%</small></div><p>Kunci paket prioritas yang berdampak langsung pada wilayah risiko.</p></div><div class="intervention-row"><div class="intervention-name"><span class="risk-dot gold-dot"></span><strong>Produksi padi</strong><small>Dinas Pertanian</small></div><div class="intervention-progress"><span style="width:82%"></span></div><div class="intervention-value"><strong>315,6</strong><small>Target 330 ribu ton</small></div><p>Periksa hambatan realisasi program sebelum triwulan IV.</p></div></section><section class="action-runway"><div class="runway-intro"><div class="eyebrow">Arah kerja berikutnya</div><h3>Satu pekan untuk mengubah temuan menjadi keputusan</h3><p>Urutan kerja dibuat berdasarkan ketergantungan data, program, dan wilayah.</p></div><div class="runway-step"><time>Hari 1–2</time><strong>Pastikan angka</strong><p>Verifikasi data kesehatan dan infrastruktur yang menjadi dasar keputusan.</p></div><div class="runway-step"><time>Hari 3–4</time><strong>Uji rencana OPD</strong><p>Bandingkan percepatan program dengan target dan kapasitas pelaksanaan.</p></div><div class="runway-step"><time>Hari 5–7</time><strong>Putuskan fokus wilayah</strong><p>Sepakati intervensi bersama untuk tiga kecamatan prioritas.</p></div></section>`}
function alertsPage(){return `${commonHead('Pusat Peringatan','Daftar isu yang memerlukan tinjauan dan tindak lanjut',`<select class="select"><option>Semua Urgensi</option><option>Kritis</option><option>Tinggi</option><option>Sedang</option></select><select class="select"><option>Semua Status</option><option>Baru</option><option>Ditinjau</option><option>Selesai</option></select>`)}<div class="metrics">${metricCard('Kritis',alerts.filter(a=>a.urgency==='Kritis').length,'Memerlukan perhatian segera','red','!')}${metricCard('Tinggi',alerts.filter(a=>a.urgency==='Tinggi').length,'Prioritas tindak lanjut','amber','▲')}${metricCard('Sedang',alerts.filter(a=>a.urgency==='Sedang').length,'Perlu pemantauan','blue','●')}${metricCard('Selesai',alerts.filter(a=>a.status==='Selesai').length,'Telah ditindaklanjuti','green','✓')}</div><div class="section-head"><div><h2>Daftar Peringatan</h2></div></div>${alertsList(20)}`}
function sourcesPageLegacy(){return `${commonHead('Sumber Data','Registry sumber resmi, jalur integrasi, dan status kesiapan',`<button class="btn" data-action="syncAll">↻ Periksa Katalog</button>`)}<div class="metrics">${metricCard('Katalog Satu Data',state.ckan.status==='siap'?'Aktif':'Diperiksa',state.ckan.count?`${fmt(state.ckan.count)} dataset terindeks`:'CKAN API publik','green','⇄')}${metricCard('Rujukan Publik BPS','Aktif','Domain Kabupaten Kapuas 6203','green','BPS')}${metricCard('Website OPD Diaudit',opdSourceRegistry.length,'Enam bidang prioritas','blue','▤')}${metricCard('Kanal Akses Terbatas',2,'Pendapatan dan kependudukan','red','⚿')}</div><section class="integration-policy"><div><strong>Prinsip integrasi</strong><p>SABABUKA tidak mengambil angka dari halaman berita. Data indikator hanya masuk melalui API, CSV/XLSX terstruktur, layanan geospasial, atau pertukaran data yang disetujui.</p></div><div><strong>Perlindungan data</strong><p>Data individu, transaksi, serta status pelayanan warga tidak masuk ke dashboard publik. Sistem menggunakan agregat sesuai kewenangan.</p></div></section><div class="section-head"><div><h2>OPD Prioritas</h2><p>Audit akses publik 12 September 2026</p></div></div><div class="table-wrap"><table><thead><tr><th>OPD</th><th>Bidang Data</th><th>Jalur Integrasi</th><th>Status</th><th>Catatan Audit</th><th>Website Resmi</th></tr></thead><tbody>${opdSourceRegistry.map(s=>`<tr><td><strong>${s.name}</strong></td><td>${s.sector}</td><td>${s.channel}</td><td>${badge(s.status)}</td><td class="source-note">${s.note}</td><td><a class="source-link" href="${s.url}" target="_blank" rel="noopener">Buka sumber</a></td></tr>`).join('')}</tbody></table></div><div class="section-head"><div><h2>Sumber Demonstrasi Internal</h2><p>Belum menjadi koneksi produksi</p></div></div><div class="table-wrap"><table><thead><tr><th>Nama Sumber</th><th>OPD Pemilik</th><th>Jenis</th><th>Jadwal</th><th>Dataset</th><th>Status</th></tr></thead><tbody>${sources.map(s=>`<tr><td><strong>${s.name}</strong></td><td>${s.owner}</td><td>${s.type}</td><td>${s.schedule}</td><td>${s.datasets}</td><td>${badge('Simulasi')}</td></tr>`).join('')}</tbody></table></div>`}
function bpsRegistryPanel(){return `<section class="bps-registry"><div class="bps-registry-head"><div class="channel-mark">BPS</div><div><span class="eyebrow">Integrasi sumber statistik resmi</span><h2>BPS Kabupaten Kapuas</h2><p>Sumber publik resmi telah dipasang sebagai rujukan provenance. Pengambilan nilai otomatis melalui WebAPI BPS disiapkan untuk domain 6203 dan memerlukan token aplikasi di backend.</p></div><span class="badge good">RUJUKAN AKTIF</span></div><div class="bps-resource-grid">${state.bps.items.map(item=>`<a href="${item.url}" target="_blank" rel="noopener"><small>${item.type}</small><strong>${item.title}</strong><span>Buka sumber resmi ↗</span></a>`).join('')}<a href="https://webapi.bps.go.id/developer" target="_blank" rel="noopener"><small>Integrasi mesin</small><strong>WebAPI BPS</strong><span>Dokumentasi API resmi ↗</span></a></div><div class="api-readiness"><strong>Status teknis:</strong> katalog publik dan tautan provenance aktif; konektor nilai otomatis menunggu token WebAPI BPS yang disimpan aman di backend, bukan di browser.</div></section>`}
function sourcesPage(){return sourcesPageLegacy().replace('<div class="metrics">',`${bpsRegistryPanel()}<div class="metrics">`)}
function validationPage(){const waiting=validations.filter(v=>v.status==='Menunggu').length,approved=validations.filter(v=>v.status==='Disetujui').length,returned=validations.filter(v=>v.status==='Perbaikan').length;return `${commonHead('Ruang Verifikasi BAPPERIDA','Gerbang kendali mutu sebelum angka dapat muncul pada Ringkasan Bupati',`<button class="btn primary" data-page="summary">Pratinjau Summary Bupati</button>`)}<section class="verification-flow"><div class="done"><span>01</span><strong>Terima</strong><small>API, CKAN, atau berkas OPD</small></div><div class="done"><span>02</span><strong>Normalisasi</strong><small>Definisi, satuan, periode, wilayah</small></div><div class="active"><span>03</span><strong>Verifikasi BAPPERIDA</strong><small>Sumber, kewajaran, dan catatan</small></div><div><span>04</span><strong>Publikasi</strong><small>Masuk Summary Bupati</small></div></section><div class="metrics">${metricCard('Menunggu Validasi',waiting,'Belum boleh tampil sebagai angka final','amber','◴')}${metricCard('Sedang Diperiksa',validations.filter(v=>v.status==='Diperiksa').length,'Pemeriksaan substansi aktif','blue','⌕')}${metricCard('Disetujui',approved+7,'Siap disajikan kepada pimpinan','green','✓')}${metricCard('Minta Perbaikan',returned+2,'Dikembalikan ke produsen data','red','↩')}</div><section class="quality-gate"><div><span class="eyebrow">Aturan kelayakan tayang</span><h2>Empat syarat sebelum data masuk ke ruang Bupati</h2></div><ul><li><strong>Sumber sah</strong><span>Rilis BPS, katalog Satu Data, atau produsen data OPD.</span></li><li><strong>Definisi konsisten</strong><span>Satuan, periode, wilayah, dan metode dapat dibandingkan.</span></li><li><strong>Jejak perubahan</strong><span>Nilai lama, nilai baru, alasan, dan pemeriksa tercatat.</span></li><li><strong>Catatan keputusan</strong><span>Batas penggunaan dan risiko salah tafsir dijelaskan.</span></li></ul></section><div class="section-head"><div><h2>Antrean Validasi</h2><p>Persetujuan akan mengubah status data menjadi layak tayang pada sesi demonstrasi.</p></div></div><div class="table-wrap"><table><thead><tr><th>Indikator</th><th>OPD</th><th>Sebelumnya</th><th>Terbaru</th><th>Perubahan</th><th>Sumber</th><th>Tanggal Masuk</th><th>Status</th><th>Aksi</th></tr></thead><tbody>${validations.map(v=>`<tr><td><strong>${v.indicator}</strong></td><td>${v.opd}</td><td>${v.prev}</td><td>${v.latest}</td><td>${v.change}</td><td>${v.source}</td><td>${v.date}</td><td>${badge(v.status)}</td><td><button class="btn" data-detail="validation:${v.id}">${v.status==='Disetujui'?'Lihat jejak':'Periksa'}</button></td></tr>`).join('')}</tbody></table></div>`}
function settingsPage(){return `${commonHead('Pengaturan','Preferensi tampilan untuk sesi presentasi') }<div class="card" style="max-width:760px"><div class="card-title"><h3>Preferensi Dashboard</h3></div><div class="indicator-row" style="padding:14px 0;border-bottom:1px solid var(--line)"><div><strong>Mode Presentasi</strong><div class="topbar-meta">Memperluas area konten dan menyederhanakan elemen administratif.</div></div><button class="btn" id="presentationBtn2">${state.presentation?'Nonaktifkan':'Aktifkan'}</button></div><div class="indicator-row" style="padding:14px 0;border-bottom:1px solid var(--line)"><div><strong>Tahun Aktif</strong><div class="topbar-meta">Periode utama dashboard.</div></div><select class="select" id="yearSelect2">${years.map(y=>`<option ${y===state.year?'selected':''}>${y}</option>`).join('')}</select></div><div class="indicator-row" style="padding:14px 0"><div><strong>Reset Pengaturan Tampilan</strong><div class="topbar-meta">Mengembalikan sidebar dan filter ke kondisi awal.</div></div><button class="btn" data-action="resetAll">Reset</button></div></div>`}
const escapeHtml=value=>String(value).replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[char]));
function chatbotReply(question){const q=question.toLowerCase();const critical=indicators.filter(i=>i.status==='critical');const priority=[...districts].sort((a,b)=>a.score-b.score).slice(0,3);const bestOpd=[...opds].sort((a,b)=>b.score-a.score).slice(0,3);const indicator=indicators.find(i=>q.includes(i.name.toLowerCase().split(' ')[0])||q.includes(i.id));if(q.includes('stunting')||q.includes('tren kesehatan')){const i=indicators.find(x=>x.id==='stunting');return `Prevalensi stunting berubah ${i.trend.map((v,index)=>`${years[index]}: ${fmt(v)}%`).join(' · ')}. Sempat naik pada 2024, kemudian turun menjadi ${fmt(i.value)}% pada 2026. Nilainya masih ${fmt(i.value-i.target)} poin di atas target ${fmt(i.target)}%.`};if(q.includes('kritis')||q.includes('perhatian'))return `${critical.length} indikator berstatus kritis: ${critical.map(i=>`${i.name} (${fmt(i.value)} ${i.unit}; target ${fmt(i.target)} ${i.unit})`).join(', ')}. Pemilik tindak lanjut: ${[...new Set(critical.map(i=>i.opd))].join(', ')}.`;if(q.includes('kecamatan')||q.includes('wilayah'))return `Wilayah dengan skor komposit terendah adalah ${priority.map(d=>`${d.name} (${d.score})`).join(', ')}. Pola risikonya konsisten pada stunting ${priority.map(d=>d.stunting+'%').join(', ')} dan jalan mantap ${priority.map(d=>d.roads+'%').join(', ')}.`;if(q.includes('opd')||q.includes('kinerja'))return `Tiga capaian OPD tertinggi adalah ${bestOpd.map(o=>`${o.name} ${o.score}%`).join(', ')}. OPD yang perlu perhatian berjumlah ${opds.filter(o=>o.status!=='Baik').length}, terutama yang terkait indikator jalan, pertanian, dan pembaruan data wilayah.`;if(q.includes('anggaran')||q.includes('keuangan'))return `Penyerapan anggaran Agustus 2026 sebesar ${fmt(finance.absorption)}%, atau ${fmt(finance.targetIncome?60-finance.absorption:1.3)} poin di bawah target periode 60%. Pola bulanan: ${finance.monthly.map((v,i)=>`${['Mar','Apr','Mei','Jun','Jul','Agu'][i]} ${fmt(v)}%`).join(' · ')}.`;if(indicator)return `${indicator.name} tercatat ${fmt(indicator.value)} ${indicator.unit}, target ${fmt(indicator.target)} ${indicator.unit}, status ${statusLabel(indicator.status)}. Time series: ${indicator.trend.map((v,index)=>`${years[index]} ${fmt(v)}`).join(' · ')}. Sumber demonstrasi: ${indicator.opd}, periode ${indicator.period}.`;return `Ringkasan data dummy 2026: ${indicators.filter(i=>i.status==='good').length} indikator baik, ${indicators.filter(i=>i.status==='attention').length} perlu perhatian, dan ${critical.length} kritis. Coba tanyakan “tren stunting”, “wilayah prioritas”, “indikator kritis”, “kinerja OPD”, atau “penyerapan anggaran”.`}
function assistantPage(){const prompts=['Ringkas kondisi daerah','Apa indikator kritis?','Bagaimana tren stunting?','Kecamatan mana yang prioritas?','Bagaimana kinerja OPD?','Berapa penyerapan anggaran?'];return `${commonHead('Asisten Data','Simulasi chatbot interaktif yang membaca dataset dummy SABABUKA',`<span class="badge attention">SIMULASI · DATA DUMMY</span>`)}<div class="chat-layout"><aside class="chat-context"><div class="chat-context-head"><span class="chat-logo">S</span><div><strong>Ruang lingkup jawaban</strong><small>Dataset demonstrasi 2022–2026</small></div></div><dl><div><dt>${indicators.length}</dt><dd>indikator strategis</dd></div><div><dt>${districts.length}</dt><dd>kecamatan</dd></div><div><dt>${opds.length}</dt><dd>OPD terpantau</dd></div><div><dt>${sources.length}</dt><dd>sumber data</dd></div></dl><p>Jawaban dibuat lokal di browser dan hanya merujuk data dummy pada dashboard ini. Tidak ada pesan yang dikirim ke layanan eksternal.</p><div class="chat-suggestions">${prompts.map(p=>`<button type="button" data-chat-prompt="${p}">${p}</button>`).join('')}</div></aside><section class="chat-panel" aria-label="Percakapan Asisten Data"><div class="chat-header"><div><strong>Asisten Data SABABUKA</strong><span><i></i> Siap membaca data demonstrasi</span></div><button class="btn" type="button" id="clearChat">Bersihkan</button></div><div class="chat-thread" id="chatThread" aria-live="polite">${state.chatMessages.map(m=>`<article class="chat-message ${m.role}"><div class="chat-avatar">${m.role==='assistant'?'S':'BK'}</div><div class="chat-bubble"><p>${escapeHtml(m.text)}</p><small>${escapeHtml(m.meta||'Pertanyaan pengguna')}</small></div></article>`).join('')}${state.chatTyping?`<article class="chat-message assistant"><div class="chat-avatar">S</div><div class="chat-bubble typing"><span></span><span></span><span></span></div></article>`:''}</div><form class="chat-compose" id="chatForm"><label for="chatInput">Tanyakan data Kabupaten Kapuas</label><div><input id="chatInput" maxlength="240" autocomplete="off" placeholder="Contoh: bagaimana tren stunting?"><button class="btn primary" type="submit" ${state.chatTyping?'disabled':''}>Kirim</button></div><small>Simulasi frontend · jawaban tidak menggunakan AI/API eksternal</small></form></section></div>`}
function pageContent(){const stateParam=new URLSearchParams(location.search).get('state');if(stateParam==='error')return `<div class="errorbox"><strong>Data belum dapat ditampilkan.</strong><p>Terjadi kendala saat memuat tampilan. Gunakan tombol muat ulang untuk mencoba kembali.</p><button class="btn" onclick="location.href=location.pathname">Muat Ulang</button></div>`;if(state.loading)return `<div class="loading-view">${Array(8).fill('<div class="skeleton"></div>').join('')}</div>`;return ({summary:meetingSummary,map:mapPage,opd:opdPage,finance:meetingFinance,services:meetingServices,analysis:meetingAnalysis,assistant:assistantPage,alerts:alertsPage,sources:meetingSources,validation:meetingValidation,settings:settingsPage}[state.page]||meetingSummary)()}
function indicatorDetail(i){const k=indicatorKnowledge[i.id],change=i.value-i.prev,improving=i.higher?change>=0:change<=0;return `<div class="detail-hero"><div><span class="eyebrow">Bahan paparan indikator</span><h2>${i.name}</h2><p>${k.definition}</p></div>${badge(statusLabel(i.status))}</div><div class="detail-values"><div><small>Nilai ${state.year}</small><strong>${fmt(i.value)} ${i.unit}</strong></div><div><small>Target</small><strong>${fmt(i.target)} ${i.unit}</strong></div><div><small>Perubahan</small><strong class="${improving?'trend-up':'trend-down'}">${change>=0?'+':''}${fmt(change)} ${i.unit}</strong></div></div><section class="narrative-block"><span>Yang disampaikan</span><p>“Pada ${state.year}, ${i.name.toLowerCase()} tercatat ${fmt(i.value)} ${i.unit}. Dibandingkan periode sebelumnya terjadi ${improving?'perbaikan':'perubahan yang perlu dicermati'} sebesar ${fmt(Math.abs(change))} ${i.unit}. Posisi saat ini ${i.status==='good'?'telah memenuhi':'belum memenuhi'} target ${fmt(i.target)} ${i.unit}. ${k.interpretation}”</p></section><dl class="parameter-list"><div><dt>Parameter</dt><dd>${k.parameter}</dd></div><div><dt>Relevansi kebijakan</dt><dd>${k.policy}</dd></div><div><dt>Sumber utama</dt><dd>${k.primary}</dd></div><div><dt>Data pendukung</dt><dd>${k.support}</dd></div><div><dt>Dataset rujukan</dt><dd>${k.reference}</dd></div></dl><div class="source-boundary"><strong>Status data pada prototipe</strong><p>Nilai masih data demonstrasi. Pada implementasi, setiap angka membawa identitas sumber, periode, wilayah, metode, versi, dan status validasi.</p></div><div class="access-scope"><strong>Batas publikasi</strong><p>Publik dan akademisi menerima indikator agregat beserta metodologi. OPD menerima rincian sektoral sesuai kewenangan. BAPPERIDA dan Bupati menerima analisis lintas sektor serta tindak lanjut internal.</p></div>`}
function districtDetail(d){return `<div class="detail-hero"><div><span class="eyebrow">Profil geospasial terhubung</span><h2>Kecamatan ${d.name}</h2><p>Ringkasan wilayah menghubungkan statistik resmi, data sektoral OPD, dan target perencanaan tanpa melebur sumbernya.</p></div>${badge(d.score>=80?'Baik':d.score>=68?'Perlu Perhatian':'Kritis')}</div><div class="detail-values"><div><small>Skor simulasi</small><strong>${d.score}</strong></div><div><small>Kemiskinan</small><strong>${d.poverty}%</strong></div><div><small>Stunting</small><strong>${d.stunting}%</strong></div><div><small>Jalan mantap</small><strong>${d.roads}%</strong></div></div><section class="narrative-block"><span>Narasi wilayah</span><p>“Profil ${d.name} memperlihatkan hubungan antara kondisi sosial ekonomi, kesehatan, dan infrastruktur. Angka perlu dibaca menurut tahun, cakupan wilayah, serta sumbernya sebelum menjadi dasar penetapan lokasi prioritas.”</p></section><div class="dataset-ledger"><div><strong>BPS dan Susenas</strong><small>Kemiskinan, rumah tangga, pendidikan, serta akses layanan dasar</small><em>Statistik resmi</em></div><div><strong>Data OPD</strong><small>Program, layanan, fasilitas, ruas jalan, dan data administrasi sektoral</small><em>Konfirmasi OPD</em></div><div><strong>BAPPENAS dan dokumen daerah</strong><small>Target pembangunan, arah kebijakan, serta indikator perencanaan</small><em>Rujukan target</em></div></div><div class="source-boundary"><strong>Aturan jika angka berbeda</strong><p>Sistem menampilkan setiap versi beserta definisi dan sumbernya. BAPPERIDA memilih angka yang layak untuk konteks perencanaan setelah OPD mengonfirmasi substansi.</p></div><div class="access-scope"><strong>Tampilan publik</strong><p>Data agregat dan metodologi dapat dipublikasikan. Data individu, data sensitif, analisis risiko rinci, dan rekomendasi internal hanya tersedia untuk pengguna berwenang.</p></div>`}
function drawer(){if(!state.drawer)return '';let [type,id]=state.drawer.split(':');if(type==='indicator'||type==='district'){const body=type==='indicator'?indicatorDetail(indicators.find(x=>x.id===id)):districtDetail(districts.find(x=>x.name===decodeURIComponent(id)));return `<div class="drawer-overlay open" id="drawerOverlay"><aside class="drawer evidence-drawer" role="dialog" aria-modal="true"><div class="drawer-head"><strong>${type==='indicator'?'Penjelasan indikator':'Detail wilayah'}</strong><button class="icon-btn" id="closeDrawer">×</button></div>${body}</aside></div>`}let content='';if(type==='opd'){const o=opds.find(x=>x.id===+id);content=`<h2>${o.name}</h2><p class="topbar-meta">Ringkasan capaian dan kualitas data</p><div class="metrics" style="grid-template-columns:1fr 1fr;margin-top:16px">${metricCard('Capaian',o.score+'%','Skor indikator strategis','green','✓')}${metricCard('Indikator',o.count,'Indikator terpantau','blue','▦')}</div><div class="card" style="margin-top:14px"><h3>Riwayat Status</h3><p>28 Agu · Pembaruan diterima</p><p>26 Agu · Validasi indikator selesai</p><p>22 Agu · Sinkronisasi sumber berhasil</p></div>`}else if(type==='alert'){const a=alerts.find(x=>x.id===+id);content=`<h2>${a.title}</h2><p>${badge(a.urgency)} ${badge(a.status)}</p><div class="card"><strong>${a.opd}</strong><p class="topbar-meta">Jenis: ${a.type} · ${a.time}</p><p>Peringatan ini masuk ke pusat pemantauan dan membutuhkan konfirmasi tindak lanjut.</p></div><div class="card" style="margin-top:12px"><h3>Timeline Tindak Lanjut</h3><p>07.14 WIB · Peringatan terdeteksi</p><p>07.19 WIB · Masuk antrean pimpinan</p></div><div style="display:flex;gap:8px;margin-top:14px;flex-wrap:wrap"><button class="btn soft" data-action="reviewAlert">Tandai Ditinjau</button><button class="btn" data-action="forwardAlert">Teruskan ke OPD</button><button class="btn primary" data-action="resolveAlert">Selesaikan</button></div>`}else if(type==='validation'){const v=validations.find(x=>x.id===+id);content=`<h2>Periksa ${v.indicator}</h2><p class="topbar-meta">${v.opd} · ${v.source}</p><div class="metrics" style="grid-template-columns:1fr 1fr;margin-top:16px">${metricCard('Nilai Sebelumnya',v.prev,'Periode sebelumnya','blue','←')}${metricCard('Nilai Terbaru',v.latest,`Perubahan ${v.change}`,'amber','→')}</div><div class="card" style="margin-top:14px"><h3>Catatan Validator</h3><textarea id="validatorNote" style="width:100%;min-height:100px;border:1px solid var(--line);border-radius:10px;padding:10px" placeholder="Tambahkan catatan pemeriksaan..."></textarea></div><div style="display:flex;gap:8px;margin-top:14px;flex-wrap:wrap"><button class="btn primary" data-action="approveValidation">Setujui</button><button class="btn" data-action="fixValidation">Minta Perbaikan</button><button class="btn danger" data-action="rejectValidation">Tolak</button></div>`}return `<div class="drawer-overlay open" id="drawerOverlay"><aside class="drawer" role="dialog" aria-modal="true"><div class="drawer-head"><strong>Detail</strong><button class="icon-btn" id="closeDrawer">×</button></div>${content}</aside></div>`}
function searchModal(){return `<div class="modal-overlay" id="searchModal"><div class="modal"><div class="drawer-head"><strong>Pencarian Dashboard</strong><button class="icon-btn" data-close-modal>×</button></div><input class="search" id="globalSearch" style="width:100%" autofocus placeholder="Cari indikator, OPD, kecamatan, atau menu"><div id="searchResults" style="margin-top:12px"><div class="empty">Ketik kata kunci untuk mencari seluruh dashboard.</div></div></div></div>`}
function syncYearView(){const period=document.querySelector('.period');if(period)period.textContent=`Periode: Agustus ${state.year}`;if(state.page==='finance'){const values=document.querySelectorAll('.finance-grid .value');if(values.length>=4){values[0].textContent=`Rp${fmt(finance.income)} T`;values[1].textContent=`Rp${fmt(finance.spend)} T`;values[2].textContent=`${fmt(finance.absorption)}%`;values[3].textContent=`${fmt(finance.absorption-60)} pt`}}if(state.page==='services'){const values=document.querySelectorAll('.service-grid .value');const avg=services.reduce((sum,item)=>sum+item.time,0)/services.length;if(values[2])values[2].textContent=`${fmt(avg)} hari`}}
function render(){applyYear(state.year);if(state.year===2026)indicators.forEach((item,index)=>item.status=baseDataset.indicators[index].status);document.querySelector('#app').innerHTML=`<div class="app ${state.collapsed?'sidebar-collapsed':''} ${state.presentation?'presentation':''}">${sidebar()}<div class="mobile-overlay ${state.mobile?'open':''}" id="mobileOverlay"></div><main class="main">${header()}<div class="content">${pageContent()}</div></main>${drawer()}</div>`;syncYearView();bind();if(state.page==='summary'&&state.ckan.status==='memuat')setTimeout(loadKapuasCatalog,0);if(['summary','sources'].includes(state.page))setTimeout(loadBpsCatalog,0)}
function bind(){document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{state.page=b.dataset.page;state.mobile=false;state.loading=true;history.replaceState({},'',location.pathname+'?page='+state.page);render();setTimeout(()=>{state.loading=false;render()},250)});document.querySelector('#collapseBtn')?.addEventListener('click',()=>{state.collapsed=!state.collapsed;render()});document.querySelector('#mobileMenu')?.addEventListener('click',()=>{state.mobile=true;render()});document.querySelector('#mobileOverlay')?.addEventListener('click',()=>{state.mobile=false;render()});document.querySelector('#yearSelect')?.addEventListener('change',e=>{state.year=+e.target.value;toast('Tahun tampilan diubah ke '+state.year);render()});document.querySelector('#yearSelect2')?.addEventListener('change',e=>{state.year=+e.target.value;render()});document.querySelectorAll('#presentationBtn,#presentationBtn2').forEach(b=>b.onclick=()=>{state.presentation=!state.presentation;state.collapsed=state.presentation;toast(state.presentation?'Mode Presentasi diaktifkan':'Mode Presentasi dinonaktifkan');render()});document.querySelector('#profile')?.addEventListener('click',e=>{if(e.target.closest('.profile-menu'))return;state.profile=!state.profile;render()});document.querySelector('#searchBtn')?.addEventListener('click',()=>{document.body.insertAdjacentHTML('beforeend',searchModal());bindSearch()});document.querySelector('#notifBtn')?.addEventListener('click',()=>{state.page='alerts';state.loading=false;render()});document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{state.chartTab=b.dataset.tab;render()});document.querySelectorAll('[data-district]').forEach(b=>b.onclick=()=>{state.district=b.dataset.district;state.drawer='district:'+encodeURIComponent(b.dataset.district);render()});document.querySelectorAll('[data-detail]').forEach(b=>{b.onclick=()=>{state.drawer=b.dataset.detail;render()};b.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();state.drawer=b.dataset.detail;render()}}});document.querySelector('#closeDrawer')?.addEventListener('click',()=>{state.drawer=null;render()});document.querySelector('#drawerOverlay')?.addEventListener('click',e=>{if(e.target.id==='drawerOverlay'){state.drawer=null;render()}});document.querySelector('#statusFilter')?.addEventListener('change',e=>{state.status=e.target.value;render()});document.querySelector('#opdSearch')?.addEventListener('input',e=>{state.search=e.target.value;setTimeout(render,80)});document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>handleAction(b.dataset.action));document.querySelectorAll('[data-sync]').forEach(b=>b.onclick=()=>syncOne(b));const sendChat=question=>{const text=question.trim();if(!text||state.chatTyping)return;state.chatMessages.push({role:'user',text});state.chatTyping=true;render();setTimeout(()=>{state.chatMessages.push({role:'assistant',text:chatbotReply(text),meta:'Asisten Data · Data dummy 2022–2026'});state.chatTyping=false;render();requestAnimationFrame(()=>{const thread=document.querySelector('#chatThread');if(thread)thread.scrollTop=thread.scrollHeight})},550)};document.querySelector('#chatForm')?.addEventListener('submit',e=>{e.preventDefault();sendChat(document.querySelector('#chatInput').value)});document.querySelectorAll('[data-chat-prompt]').forEach(b=>b.onclick=()=>sendChat(b.dataset.chatPrompt));document.querySelector('#clearChat')?.addEventListener('click',()=>{state.chatMessages=state.chatMessages.slice(0,1);state.chatTyping=false;render()});document.onkeydown=e=>{if(e.key==='Escape'){document.querySelector('.modal-overlay')?.remove();if(state.drawer){state.drawer=null;render()}if(state.mobile){state.mobile=false;render()}}}}
function bindSearch(){const m=document.querySelector('#searchModal');m.querySelector('[data-close-modal]').onclick=()=>m.remove();m.onclick=e=>{if(e.target===m)m.remove()};const input=m.querySelector('#globalSearch'),res=m.querySelector('#searchResults');input.oninput=()=>{const q=input.value.toLowerCase().trim();if(!q){res.innerHTML='<div class="empty">Ketik kata kunci untuk mencari seluruh dashboard.</div>';return}const found=[...indicators.map(i=>({name:i.name,meta:i.opd,go:()=>{m.remove();state.page='summary';state.drawer='indicator:'+i.id;state.loading=false;render()}})),...opds.map(o=>({name:o.name,meta:'OPD',go:()=>{m.remove();state.page='opd';state.drawer='opd:'+o.id;state.loading=false;render()}})),...districts.map(d=>({name:d.name,meta:'Kecamatan',go:()=>{m.remove();state.page='map';state.district=d.name;state.loading=false;render()}}))].filter(x=>x.name.toLowerCase().includes(q)).slice(0,8);res.innerHTML=found.length?found.map((x,i)=>`<button class="nav-item" style="color:var(--ink);background:#f6f8fa" data-result="${i}"><span class="nav-icon">⌕</span><span><strong>${x.name}</strong><br><small>${x.meta}</small></span></button>`).join(''):'<div class="empty">Tidak ada hasil yang cocok.</div>';res.querySelectorAll('[data-result]').forEach(b=>b.onclick=found[+b.dataset.result].go)}}
function handleAction(a){
  if(a==='report'||a==='export'){
    const text='SABABUKA BERSINAR\nBrief Pimpinan Kabupaten Kapuas\nPeriode Agustus '+state.year+'\n\nIndikator layak tampil: 10 dari '+indicators.length+'\nIndikator kritis: '+indicators.filter(i=>i.status==='critical').length+'\nMenunggu konfirmasi BAPPERIDA: 2\n\nSumber: BPS Kabupaten Kapuas, Satu Data Kabupaten Kapuas, dan data sektoral OPD.\nCatatan: nilai pada prototipe masih data demonstrasi.';
    const blob=new Blob([text],{type:'text/plain'}),url=URL.createObjectURL(blob),link=document.createElement('a');
    link.href=url;link.download=a==='report'?'brief-pimpinan-sababuka.txt':'ringkasan-keuangan-sababuka.txt';link.click();URL.revokeObjectURL(url);toast('Brief pimpinan berhasil dibuat');
  }else if(a==='reset'){state.status='Semua';state.search='';toast('Filter direset');render()
  }else if(a==='resetAll'){state.collapsed=false;state.presentation=false;state.status='Semua';state.search='';toast('Pengaturan tampilan direset');render()
  }else if(a==='syncAll'){toast('Pemeriksaan katalog resmi dimulai');setTimeout(()=>toast('BPS, Satu Data, dan sumber OPD selesai diperiksa'),900)
  }else if(['reviewAlert','forwardAlert','resolveAlert'].includes(a)){toast(a==='reviewAlert'?'Peringatan ditandai sudah ditinjau':a==='forwardAlert'?'Peringatan diteruskan ke OPD':'Peringatan ditandai selesai');state.drawer=null;render()
  }else if(['approveValidation','fixValidation','rejectValidation'].includes(a)){
    const id=state.drawer?.startsWith('validation:')?+state.drawer.split(':')[1]:null,v=validations.find(item=>item.id===id);
    if(v)v.status=a==='approveValidation'?'Disetujui':a==='fixValidation'?'Perbaikan':'Ditolak';
    toast(a==='approveValidation'?'Simulasi: contoh ditandai lolos pemeriksaan':a==='fixValidation'?'Simulasi: contoh dikembalikan untuk perbaikan':'Simulasi: contoh tidak dilanjutkan');state.drawer=null;render();
  }else if(a==='metric'){toast('Rincian metrik tersedia pada halaman terkait')
  }else if(a==='help'){toast('Gunakan Mode Presentasi untuk tampilan proyektor yang lebih luas')
  }else if(a==='profile'){toast((state.role==='bapperida'?'Contoh ruang verifikasi':'Contoh tampilan pimpinan')+' aktif pada sesi ini')}
}
function syncOne(btn){btn.classList.add('syncing');btn.textContent='↻ Memproses';setTimeout(()=>{btn.classList.remove('syncing');btn.textContent='↻ Sinkronkan';const id=btn.dataset.sync;document.querySelector('#last-'+id).textContent='28 Agu, 07.45';toast('Sinkronisasi sumber berhasil')},700)}
document.addEventListener('change',event=>{if(event.target.id==='roleSelect'){state.role=event.target.value;state.page=state.role==='bapperida'?'validation':'summary';state.loading=false;history.replaceState({},'',location.pathname+'?page='+state.page);render();toast(state.role==='bapperida'?'Simulasi verifikasi dibuka':'Contoh tampilan pimpinan dibuka')}});
const qp=new URLSearchParams(location.search);if(qp.get('page')&&titleMap[qp.get('page')])state.page=qp.get('page');render();setTimeout(()=>{state.loading=false;render()},350);
